Problem:
A butcher sells marinated wild boar and processed lamb chops. Each portion of marinated wild boar requires 3 minutes of preparation and 6 ounces of meat. One portion of processed lamb chops requires 1 minute of preparation and 7 ounces of meat. Since processed lamb chops are more popular and common, the butcher plans to make at least twice as many processed lamb chops as marinated wild boars. The butcher has a small staff and only has available 250 collective minutes every week to preparing these two items and only has available 1375 ounces of meat. If a portion of marinated wild boar sells for a revenue of 6 dollars whereas a portion of processed lamb chops sells for a revenue of 4 dollars, how many of each should the butcher make to maximize their revenue?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "marinated wild boar portions",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "processed lamb chop portions",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "max",
   "terms": [
    {
     "var": "marinated wild boar portions",
     "coef": 6.0
    },
    {
     "var": "processed lamb chop portions",
     "coef": 4.0
    }
   ]
  },
  "constraints": [
   {
    "name": "preparation_minutes",
    "terms": [
     {
      "var": "marinated wild boar portions",
      "coef": 3.0
     },
     {
      "var": "processed lamb chop portions",
      "coef": 1.0
     }
    ],
    "sense": "<=",
    "rhs": 250.0
   },
   {
    "name": "meat_ounces",
    "terms": [
     {
      "var": "marinated wild boar portions",
      "coef": 6.0
     },
     {
      "var": "processed lamb chop portions",
      "coef": 7.0
     }
    ],
    "sense": "<=",
    "rhs": 1375.0
   },
   {
    "name": "lamb_at_least_twice_boar",
    "terms": [
     {
      "var": "processed lamb chop portions",
      "coef": 1.0
     },
     {
      "var": "marinated wild boar portions",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 850.0,
  "values": {
   "marinated wild boar portions": 25.0,
   "processed lamb chop portions": 175.0
  },
  "binding": [
   "preparation_minutes",
   "meat_ounces"
  ],
  "slack": {
   "preparation_minutes": 0.0,
   "meat_ounces": 0.0,
   "lamb_at_least_twice_boar": 125.0
  },
  "shadow_prices": null,
  "limits": {
   "preparation_minutes": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "meat_ounces": {
    "dropped_improves": true,
    "loosened_improves": false
   },
   "lamb_at_least_twice_boar": {
    "dropped_improves": false,
    "loosened_improves": false
   }
  }
 }
}
